      "question_id": "Q2",
      "answered_aspects": [
        {
          "aspect_id": "Q2-A1",
          "claim": "劉孝標注指出太傅為謝安（安），因其未仕而高臥東山，故對其在軍前之事表示懷疑。",
          "evidence": [
            {
              "ref": "L02",
              "quote": "安猶未仕高臥東山又何肯輕入軍旅邪"
            }
          ]
        }
      ],
      "unanswered_aspects": [
        {
          "aspect_id": "Q2-U1",
          "gap": "太傅與謝中郎的具體關係未說明，影響理解太傅沉默的態度是否為親屬間的包容或另有含意。",
          "reading_impact": "medium"
        }
      ],
      "conflicts": [],
      "reading_sufficient": false,
      "historical_verification_open": true
    },
    {
      "question_id": "Q3",
      "answered_aspects": [
        {
          "aspect_id": "Q3-A1",
          "claim": "劉注以『迂謬巳甚』評論此處記載，並指出太傅謝安當時未仕高臥東山，故不可能說出或發生此語，暗示此話並非太傅所言。",
          "evidence": [
            {
              "ref": "L02",
              "quote": "此言迂謬巳甚"
            },
            {
              "ref": "L02",
              "quote": "安猶未仕高臥東山又何肯輕入軍旅邪"
            }
          ]
        }
      ],
      "unanswered_aspects": [
        {
          "aspect_id": "Q3-U1",
          "gap": "劉注仍未說明『爾日猶云』的說話者究竟為太傅還是謝中郎；若太傅不在場，是否為謝中郎自語也未交代。",
          "reading_impact": "high"
        }
      ],
      "conflicts": [],
      "reading_sufficient": false,
      "historical_verification_open": true
    }
  ]
}

